-- Isolated H2 fixture, never used to migrate MySQL.
CREATE TABLE app_config (app_id VARCHAR(32) PRIMARY KEY,settings_json CLOB NOT NULL,version INT NOT NULL,updated_at_ms BIGINT NOT NULL);
CREATE TABLE compression_record (id VARCHAR(64) PRIMARY KEY,app_id VARCHAR(32) NOT NULL,file_key CLOB NOT NULL,file_key_hash CHAR(64) NOT NULL,evidence_source VARCHAR(8) NOT NULL,status VARCHAR(16) NOT NULL,record_json CLOB NOT NULL,version INT NOT NULL,idempotency_key_hash CHAR(64) NOT NULL UNIQUE,request_hash CHAR(64) NOT NULL,created_at_ms BIGINT NOT NULL,updated_at_ms BIGINT NOT NULL,UNIQUE(app_id,file_key_hash,evidence_source));
CREATE TABLE notification_delivery (id VARCHAR(64) PRIMARY KEY,app_id VARCHAR(32) NOT NULL,run_id VARCHAR(128),type VARCHAR(16) NOT NULL,purpose VARCHAR(16) NOT NULL,evidence_source VARCHAR(8) NOT NULL,destination_id VARCHAR(128) NOT NULL,business_key_hash CHAR(64) NOT NULL UNIQUE,idempotency_key_hash CHAR(64) NOT NULL UNIQUE,request_hash CHAR(64) NOT NULL,status VARCHAR(16) NOT NULL,record_json CLOB NOT NULL,attempt_count INT NOT NULL,next_attempt_at_ms BIGINT NOT NULL,created_at_ms BIGINT NOT NULL,updated_at_ms BIGINT NOT NULL,sent_at_ms BIGINT);
CREATE TABLE alert_event (id VARCHAR(64) PRIMARY KEY,app_id VARCHAR(32) NOT NULL,source_event_id VARCHAR(128) NOT NULL,event_kind VARCHAR(16) NOT NULL,incident_id VARCHAR(64) NOT NULL,payload_json CLOB NOT NULL,received_at_ms BIGINT NOT NULL,CONSTRAINT uk_alert_event_source UNIQUE(app_id,source_event_id));
CREATE TABLE alert_incident (id VARCHAR(64) PRIMARY KEY,app_id VARCHAR(32) NOT NULL,severity VARCHAR(8) NOT NULL,incident_type VARCHAR(64) NOT NULL,object_key VARCHAR(512) NOT NULL,fingerprint CHAR(64) NOT NULL,active_fingerprint VARCHAR(64),status VARCHAR(16) NOT NULL,routing_status VARCHAR(16) NOT NULL,routing_error VARCHAR(64),chat_mode VARCHAR(24),chat_id VARCHAR(128),opening_message_id VARCHAR(128),first_seen_at_ms BIGINT NOT NULL,last_seen_at_ms BIGINT NOT NULL,occurrence_count INT NOT NULL,ack_deadline_at_ms BIGINT NOT NULL,acknowledged_at_ms BIGINT,acknowledged_by VARCHAR(128),recovered_at_ms BIGINT,reminder_count INT NOT NULL,next_reminder_at_ms BIGINT,escalated_at_ms BIGINT,details_json CLOB NOT NULL,version INT NOT NULL,CONSTRAINT uk_alert_active UNIQUE(active_fingerprint));
ALTER TABLE notification_delivery ADD COLUMN incident_id VARCHAR(64);
ALTER TABLE notification_delivery ADD COLUMN alert_phase VARCHAR(32);
ALTER TABLE notification_delivery ADD COLUMN chat_id VARCHAR(128);
ALTER TABLE notification_delivery ADD COLUMN feishu_message_id VARCHAR(128);
